<template>
  <section
    ref="collectionBrowser"
    class="collection-browser index-ignore"
    @collection-target="activateTarget($event.detail)"
    :data-collection-transition-axis="transitionId ? gridCursorAxes[transitionId] : null"
    :class="[
      `is-${mode}`,
      transitionAction ? `is-transition-${transitionAction}` : '',
      {
        'is-layout-transitioning': Boolean(transitionId),
        'is-archive-open': archiveExpanded
      }
    ]"
  >
    <header v-if="curationActive" class="collection-curation-head">
      <h2>{{ featuredLabel }}</h2>
    </header>
    <div v-if="mode === 'grid'" class="collection-grid">
      <div class="collection-grid-row">
        <template v-for="(entry, entryIndex) in orderedEntries" :key="entry.id">
        <div v-if="curationActive && entryIndex === archiveStartIndex" class="collection-archive-gateway">
          <button
            type="button"
            class="collection-archive-toggle"
            :aria-expanded="archiveExpanded.toString()"
            @click="toggleArchive"
          >
            <span class="collection-archive-copy">
              <strong>{{ archiveLabel }}</strong>
              <span>{{ archiveCountLabel }}</span>
            </span>
            <span class="collection-archive-glyph" :class="{ 'is-open': archiveExpanded }" aria-hidden="true"><SiteIcon name="arrow-down" /></span>
          </button>
        </div>
        <Transition name="collection-archive-card">
        <article
          v-show="isEntryVisible(entry)"
          :id="entry.anchor || entry.id"
          class="collection-card"
          :class="{
            selected: gridLayoutId === entry.id,
            'is-archive-entry': isArchiveEntry(entry),
            'is-detail-navigable': isDetailNavigable(entry),
            'is-signature': isFeatureEntry(entry)
          }"
          :style="{
            viewTransitionName: transitionId === entry.id
              ? 'collection-active-card'
              : `collection-card-${entry.id}`,
            '--archive-delay': `${archivePosition(entry) * 28}ms`
          }"
          @click.self="!isFeatureEntry(entry) && desktopHover && toggle(entry.id)"
        >
            <SignatureProject v-if="entry.showcase" :entry="entry" />
            <template v-else>
            <button
              type="button"
              class="collection-card-summary"
              data-press-intent="custom"
              :class="{ 'is-pressed': pressedId === entry.id }"
              :aria-expanded="isEntryOpen(entry.id).toString()"
              :data-collection-toggle="isEntryOpen(entry.id) ? 'collapse' : 'expand'"
              :data-collection-axis="gridCursorAxes[entry.id]"
              @pointerdown="startPress(entry.id, $event)"
              @pointerup="finishPress(entry.id)"
              @pointercancel="cancelPress(entry.id)"
              @click="toggle(entry.id)"
            >
              <span class="collection-card-meta">
                <span>{{ entry.category }}</span>
                <span>{{ entry.period }}</span>
              </span>
              <strong>{{ entry.title }}</strong>
              <span v-if="entry.subtitle && entry.kind !== 'project'" class="collection-card-subtitle">{{ entry.subtitle }}</span>
              <span class="collection-card-preview">{{ entry.preview }}</span>
              <span class="collection-card-cue" aria-hidden="true">
                {{ gridLayoutId === entry.id ? 'Close' : 'Read' }}
                <span>{{ gridLayoutId === entry.id ? '−' : '+' }}</span>
              </span>
            </button>
            <div
              class="collection-detail-shell"
              :class="{ open: isEntryOpen(entry.id) }"
              :aria-hidden="(!isEntryOpen(entry.id)).toString()"
              :inert="isEntryOpen(entry.id) ? null : ''"
            >
              <div class="collection-detail-clip">
                <div
                  class="collection-detail collection-detail-embedded"
                  :class="{ 'collection-detail-navigable': isDetailNavigable(entry) }"
                  :role="isDetailNavigable(entry) ? 'link' : null"
                  :tabindex="isDetailNavigable(entry) ? 0 : null"
                  :aria-label="isDetailNavigable(entry) ? `Open ${entry.title}` : null"
                  @click="openDetail(entry, $event)"
                  @keydown.enter="openDetail(entry, $event)"
                >
                  <CollectionDetail :entry="entry" embedded @close="close(entry.id)" />
                </div>
              </div>
            </div>
            <button
              v-if="transitionId === entry.id"
              type="button"
              class="collection-transition-hit-area"
              :aria-label="transitionAction === 'collapse' ? `Close ${entry.title}` : `Open ${entry.title}`"
              :data-collection-toggle="transitionAction"
              :data-collection-axis="gridCursorAxes[entry.id]"
              @click.stop="toggle(entry.id)"
            ></button>
            </template>
        </article>
        </Transition>
        </template>
      </div>
    </div>

    <div v-else class="collection-index">
      <template v-for="(entry, entryIndex) in entries" :key="entry.id">
      <div v-if="curationActive && entryIndex === featuredCount" class="collection-archive-gateway">
        <button
          type="button"
          class="collection-archive-toggle"
          :aria-expanded="archiveExpanded.toString()"
          @click="toggleArchive"
        >
          <span class="collection-archive-copy">
            <strong>{{ archiveLabel }}</strong>
            <span>{{ archiveCountLabel }}</span>
          </span>
          <span class="collection-archive-glyph" :class="{ 'is-open': archiveExpanded }" aria-hidden="true"><SiteIcon name="arrow-down" /></span>
        </button>
      </div>
      <Transition name="collection-archive-card">
      <section
        v-show="isEntryVisible(entry)"
        :id="entry.anchor || entry.id"
        class="collection-index-unit"
        :class="{
          'is-archive-entry': isArchiveEntry(entry),
          'is-detail-navigable': isDetailNavigable(entry)
        }"
        :style="{ '--archive-delay': `${archivePosition(entry) * 28}ms` }"
        @click.self="desktopHover && toggle(entry.id)"
      >
        <button
          type="button"
          class="collection-index-row"
          data-press-intent="custom"
          :class="{ selected: isEntryOpen(entry.id), 'is-pressed': pressedId === entry.id }"
          :aria-expanded="isEntryOpen(entry.id).toString()"
          :data-collection-toggle="isEntryOpen(entry.id) ? 'collapse' : 'expand'"
          @pointerdown="startPress(entry.id, $event)"
          @pointerup="finishPress(entry.id)"
          @pointercancel="cancelPress(entry.id)"
          @click="toggle(entry.id)"
        >
          <span class="collection-index-category">{{ entry.category }}</span>
          <strong>{{ entry.title }}</strong>
          <span class="collection-index-period">{{ entry.period }}</span>
          <span class="collection-index-cue" aria-hidden="true">{{ isEntryOpen(entry.id) ? '−' : '+' }}</span>
        </button>
        <div
          class="collection-detail-shell"
          :class="{ open: isEntryOpen(entry.id) }"
          :aria-hidden="(!isEntryOpen(entry.id)).toString()"
          :inert="isEntryOpen(entry.id) ? null : ''"
        >
          <div class="collection-detail-clip">
            <div
              class="collection-detail collection-detail-embedded collection-index-detail"
              :class="{ 'collection-detail-navigable': isDetailNavigable(entry) }"
              :role="isDetailNavigable(entry) ? 'link' : null"
              :tabindex="isDetailNavigable(entry) ? 0 : null"
              :aria-label="isDetailNavigable(entry) ? `Open ${entry.title}` : null"
              @click="openDetail(entry, $event)"
              @keydown.enter="openDetail(entry, $event)"
            >
              <CollectionDetail :entry="entry" embedded show-subtitle @close="close(entry.id)" />
            </div>
          </div>
        </div>
      </section>
      </Transition>
      </template>
    </div>
  </section>
</template>

<script>
import { watchDesktopHover } from '../../utils/desktopHover';
import CollectionDetail from './CollectionDetail.vue';
import SignatureProject from './SignatureProject.vue';
import { acquireInteractiveCursorLock } from '../../utils/interactiveCursorLock';
import { collectionDetailRoute, shouldNavigateCollectionDetail } from '../../utils/collectionDetailNavigation';
import { ensureCollectionCursorStyles } from '../../utils/collectionCursorStyles';

const GRID_CURSOR_SETTLE_MS = 420;

export default {
  name: 'CollectionBrowser',
  components: { CollectionDetail, SignatureProject },
  emits: ['target-consumed'],
  props: {
    entries: {
      type: Array,
      required: true
    },
    mode: {
      type: String,
      required: true
    },
    targetId: {
      type: String,
      default: ''
    },
    initialOpenId: {
      type: String,
      default: ''
    },
    featuredCount: {
      type: Number,
      default: 0
    },
    featuredLabel: {
      type: String,
      default: 'Selected'
    },
    archiveLabel: {
      type: String,
      default: 'All'
    },
    searchActive: {
      type: Boolean,
      default: false
    }
  },
  data() {
    const hasInitialEntry = this.entries.some((entry) => entry.id === this.initialOpenId);
    const initialOpenId = hasInitialEntry ? this.initialOpenId : '';
    const initialOpenIndex = this.entries.findIndex((entry) => entry.id === initialOpenId);
    const archiveInitiallyExpanded = initialOpenIndex >= this.featuredCount && initialOpenIndex >= 0;
    return {
      desktopHover: false,
      openId: initialOpenId,
      indexOpenIds: initialOpenId ? [initialOpenId] : [],
      layoutId: this.mode === 'grid' ? initialOpenId : '',
      transitionId: '',
      transitionAction: '',
      pressedId: '',
      archiveExpanded: archiveInitiallyExpanded,
      archiveVisible: archiveInitiallyExpanded
    };
  },
  computed: {
    curationActive() {
      return !this.searchActive
        && this.featuredCount > 0
        && this.entries.length > this.featuredCount;
    },
    featuredEntries() {
      return this.curationActive ? this.entries.slice(0, this.featuredCount) : this.entries;
    },
    archiveEntries() {
      return this.curationActive ? this.entries.slice(this.featuredCount) : [];
    },
    archiveIds() {
      return new Set(this.archiveEntries.map((entry) => entry.id));
    },
    archiveCountLabel() {
      return `${this.archiveEntries.length} more`;
    },
    archiveStartIndex() {
      return this.orderedEntries.findIndex((entry) => this.isArchiveEntry(entry));
    },
    gridCursorAxes() {
      const axes = {};
      let column = 0;
      let archive = false;
      this.orderedEntries.filter((entry) => this.isEntryVisible(entry)).forEach((entry) => {
        const nextArchive = this.isArchiveEntry(entry);
        if (nextArchive !== archive) column = 0;
        archive = nextArchive;
        if (this.isFeatureEntry(entry)) {
          column = 0;
        } else if (entry.id === this.gridLayoutId) {
          // The full-width card returns to its original column on collapse.
          let originalColumn = 0;
          let originalArchive = false;
          for (const item of this.entries) {
            if (!this.isEntryVisible(item)) continue;
            const nextArchive = this.isArchiveEntry(item);
            if (nextArchive !== originalArchive) originalColumn = 0;
            originalArchive = nextArchive;
            if (item.id === entry.id) break;
            originalColumn = this.isFeatureEntry(item) ? 0 : (originalColumn + 1) % 2;
          }
          axes[entry.id] = originalColumn ? 'right' : 'left';
          column = 0;
        } else {
          axes[entry.id] = column % 2 ? 'right' : 'left';
          column += 1;
        }
      });
      return axes;
    },
    gridLayoutId() {
      const id = this.openId || this.layoutId;
      return this.mode === 'grid' && !this.isFeatureEntry(this.entries.find(entry => entry.id === id)) ? id : '';
    },
    orderedEntries() {
      if (!this.gridLayoutId) return this.entries;
      const selectedIndex = this.entries.findIndex((entry) => entry.id === this.gridLayoutId);
      if (selectedIndex < 0) return this.entries;

      // Signature projects occupy their own row, including filtered results.
      let rowStart = 0;
      let column = 0;
      let archive = false;
      for (let index = 0; index <= selectedIndex; index += 1) {
        const entry = this.entries[index];
        const nextArchive = this.isArchiveEntry(entry);
        if (nextArchive !== archive) column = 0;
        archive = nextArchive;
        if (this.isFeatureEntry(entry) || column === 0) rowStart = index;
        column = this.isFeatureEntry(entry) ? 0 : (column + 1) % 2;
      }
      const before = this.entries.slice(0, rowStart);
      const fromRow = this.entries.slice(rowStart);
      const selected = this.entries[selectedIndex];
      return [...before, selected, ...fromRow.filter((entry) => entry.id !== this.gridLayoutId)];
    }
  },
  watch: {
    mode(nextMode) {
      window.clearTimeout(this._layoutTimer);
      window.clearTimeout(this._activationTimer);
      this.pressedId = '';
      this.transitionId = '';
      this.transitionAction = '';
      if (nextMode === 'index') {
        if (this.openId && !this.indexOpenIds.includes(this.openId)) {
          this.indexOpenIds = [...this.indexOpenIds, this.openId];
        }
        this.layoutId = '';
        return;
      }
      const nextGridId = this.openId || this.indexOpenIds[this.indexOpenIds.length - 1] || '';
      this.openId = nextGridId;
      this.layoutId = nextGridId;
    },
    entries() {
      const validIds = new Set(this.entries.map((entry) => entry.id));
      this.indexOpenIds = this.indexOpenIds.filter((id) => validIds.has(id));
      if (this.openId && !validIds.has(this.openId)) {
        this.openId = this.indexOpenIds[this.indexOpenIds.length - 1] || '';
      }
      if (this.layoutId && !validIds.has(this.layoutId)) this.layoutId = '';
    },
    targetId: {
      immediate: true,
      handler(id) {
        if (id) this.activateTarget(id);
      }
    }
  },
  mounted() {
    ensureCollectionCursorStyles();
    this._stopHover = watchDesktopHover(value => { this.desktopHover = value; });
  },
  unmounted() {
    this._stopHover?.();
    window.clearTimeout(this._layoutTimer);
    window.clearTimeout(this._pressIntentTimer);
    window.clearTimeout(this._pressTimer);
    window.clearTimeout(this._activationTimer);
    window.clearTimeout(this._gridReverseTimer);
    window.clearTimeout(this._archiveCleanupTimer);
    window.clearTimeout(this._archiveAnimationTimer);
    if (this._archiveAnimationFrame) cancelAnimationFrame(this._archiveAnimationFrame);
    if (this._gridCursorTimers) {
      this._gridCursorTimers.forEach((timer) => window.clearTimeout(timer));
      this._gridCursorTimers.clear();
    }
    if (this._gridCursorReleases) {
      this._gridCursorReleases.forEach((release) => release());
      this._gridCursorReleases.clear();
    }
    if (this._indexAnchorFrame) cancelAnimationFrame(this._indexAnchorFrame);
    if (this._gridTransition && this._gridTransition.skipTransition) {
      this._gridTransition.skipTransition();
    }
  },
  methods: {
    isEntryOpen(id) {
      return this.mode === 'index'
        ? this.indexOpenIds.includes(id)
        : this.openId === id;
    },
    isArchiveEntry(entry) {
      return this.curationActive && this.archiveIds.has(entry.id);
    },
    isEntryVisible(entry) {
      return !this.isArchiveEntry(entry) || this.archiveVisible;
    },
    archivePosition(entry) {
      const index = this.archiveEntries.findIndex((item) => item.id === entry.id);
      return Math.max(0, index);
    },
    clearArchiveOpenState() {
      if (this.mode === 'grid' && this.archiveIds.has(this.openId)) {
        this.openId = '';
        this.layoutId = '';
        this.transitionId = '';
        this.transitionAction = '';
      }
      if (this.mode === 'index') {
        this.indexOpenIds = this.indexOpenIds.filter((id) => !this.archiveIds.has(id));
        this.openId = this.indexOpenIds[this.indexOpenIds.length - 1] || '';
      }
    },
    archiveSpanHeight() {
      const browser = this.$refs.collectionBrowser;
      if (!browser) return 0;
      const entries = Array.from(browser.querySelectorAll('.is-archive-entry'))
        .filter((element) => element.getClientRects().length > 0);
      if (!entries.length) return 0;
      const rects = entries.map((element) => element.getBoundingClientRect());
      return Math.max(...rects.map((rect) => rect.bottom))
        - Math.min(...rects.map((rect) => rect.top));
    },
    clearArchiveAnimationStyles(browser) {
      if (!browser) return;
      browser.style.height = '';
      browser.style.overflow = '';
      browser.style.transition = '';
      browser.style.willChange = '';
    },
    finishArchiveAnimation(browser, token, opening) {
      if (this._archiveAnimationToken !== token) return;
      if (!opening && !this.archiveExpanded) this.clearArchiveOpenState();
      this.$nextTick(() => {
        if (this._archiveAnimationToken !== token) return;
        this.clearArchiveAnimationStyles(browser);
      });
    },
    async toggleArchive() {
      const browser = this.$refs.collectionBrowser;
      const opening = !this.archiveExpanded;
      window.clearTimeout(this._archiveAnimationTimer);
      if (this._archiveAnimationFrame) cancelAnimationFrame(this._archiveAnimationFrame);

      if (!browser || this.prefersReducedMotion()) {
        this.archiveExpanded = opening;
        this.archiveVisible = opening;
        if (!opening) this.clearArchiveOpenState();
        return;
      }

      const token = (this._archiveAnimationToken || 0) + 1;
      this._archiveAnimationToken = token;
      const startHeight = browser.getBoundingClientRect().height;
      browser.style.transition = 'none';
      browser.style.height = `${startHeight}px`;
      browser.style.overflow = 'clip';
      browser.style.willChange = 'height';
      void browser.offsetHeight;

      if (opening) {
        this.archiveExpanded = true;
        this.archiveVisible = true;
        await this.$nextTick();
      } else {
        const archiveHeight = this.archiveSpanHeight();
        this.archiveExpanded = false;
        this.archiveVisible = false;
        await this.$nextTick();
        this.runArchiveHeightAnimation(browser, startHeight, startHeight - archiveHeight, token, opening);
        return;
      }

      const archiveHeight = this.archiveSpanHeight();
      this.runArchiveHeightAnimation(browser, startHeight, startHeight + archiveHeight, token, opening);
    },
    runArchiveHeightAnimation(browser, startHeight, endHeight, token, opening) {
      const duration = opening ? 440 : 380;
      browser.style.height = `${startHeight}px`;
      void browser.offsetHeight;
      this._archiveAnimationFrame = requestAnimationFrame(() => {
        if (this._archiveAnimationToken !== token) return;
        browser.style.transition = `height ${duration}ms cubic-bezier(0.4, 0, 0.2, 1)`;
        browser.style.height = `${Math.max(0, endHeight)}px`;
        this._archiveAnimationTimer = window.setTimeout(() => {
          this.finishArchiveAnimation(browser, token, opening);
        }, duration + 24);
      });
    },
    isFeatureEntry(entry) { return Boolean(entry?.showcase); },
    isDetailNavigable(entry) {
      return entry.kind !== 'project' && this.desktopHover && !(this.mode === 'grid' && this.isFeatureEntry(entry)) && this.isEntryOpen(entry.id) && Boolean(collectionDetailRoute(entry));
    },
    openDetail(entry, event) {
      if (!this.isDetailNavigable(entry) || this.transitionId) return;
      const selection = window.getSelection ? window.getSelection() : null;
      if (!shouldNavigateCollectionDetail(event, selection)) return;
      const route = collectionDetailRoute(entry);
      if (event.type === 'keydown') event.preventDefault();
      if (entry.externalPage) {
        window.open(route, '_blank', 'noopener');
        return;
      }
      if (event.metaKey || event.ctrlKey || event.shiftKey) {
        window.open(this.$router.resolve(route).href, '_blank', 'noopener');
        return;
      }
      this.$router.push(route).catch(() => {});
    },
    prefersReducedMotion() {
      return window.matchMedia
        && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    },
    activateTarget(targetId) {
      const entry = this.entries.find((item) => item.id === targetId || item.anchor === targetId);
      if (!entry) return;
      if (this.isArchiveEntry(entry)) {
        this.archiveExpanded = true;
        this.archiveVisible = true;
      }
      // A route target prepares the reading layout before the router lands.
      // Manual expansion has its own viewport hold and view transition, which
      // would fight the cross-page glide if reused here.
      if (this.mode === 'index') {
        if (!this.indexOpenIds.includes(entry.id)) this.indexOpenIds = [...this.indexOpenIds, entry.id];
        this.openId = entry.id;
        this.layoutId = '';
      } else if (!this.isFeatureEntry(entry)) {
        this.openId = entry.id;
        this.layoutId = entry.id;
      }
      this.$emit('target-consumed', targetId);
    },
    startPress(id, event) {
      if (event.pointerType === 'mouse' && event.button !== 0) return;
      window.clearTimeout(this._pressIntentTimer);
      window.clearTimeout(this._pressTimer);
      if (event.currentTarget && event.currentTarget.setPointerCapture) {
        event.currentTarget.setPointerCapture(event.pointerId);
      }
      this._pressCandidateId = id;
      this._pressIntentTimer = window.setTimeout(() => {
        if (this._pressCandidateId !== id) return;
        this._pressVisibleAt = window.performance ? window.performance.now() : Date.now();
        this.pressedId = id;
      }, 120);
    },
    finishPress(id) {
      window.clearTimeout(this._pressIntentTimer);
      this._pressCandidateId = '';
      if (this.pressedId !== id) return;
      const now = window.performance ? window.performance.now() : Date.now();
      const elapsed = now - (this._pressVisibleAt || now);
      const feedbackFloor = Math.max(0, 120 - elapsed);
      const remaining = Math.max(feedbackFloor, 150 - elapsed);

      this._releasedPressId = id;
      this._activationDelay = remaining + (this.prefersReducedMotion() ? 0 : 180);
      window.clearTimeout(this._pressTimer);
      if (remaining === 0) {
        this.pressedId = '';
        return;
      }
      this._pressTimer = window.setTimeout(() => {
        if (this.pressedId === id) this.pressedId = '';
      }, remaining);
    },
    cancelPress(id) {
      window.clearTimeout(this._pressIntentTimer);
      window.clearTimeout(this._pressTimer);
      this._pressCandidateId = '';
      this._releasedPressId = '';
      this._activationDelay = 0;
      if (this.pressedId === id) this.pressedId = '';
    },
    toggle(id) {
      const isPointerPress = this.pressedId === id || this._releasedPressId === id;
      const activationDelay = isPointerPress ? (this._activationDelay || 180) : 0;
      this._releasedPressId = '';
      this._activationDelay = 0;
      window.clearTimeout(this._activationTimer);
      if (activationDelay > 0) {
        this._activationTimer = window.setTimeout(() => this.commitToggle(id), activationDelay);
        return;
      }
      this.commitToggle(id);
    },
    commitToggle(id) {
      if (this.mode === 'index') {
        const entry = this.entries.find((item) => item.id === id);
        const target = entry && document.getElementById(entry.anchor || entry.id);
        const viewportAnchor = this.consumeTargetViewportAnchor(id) || (target ? {
          kind: 'top',
          entryId: id,
          id: entry.anchor || entry.id,
          top: target.getBoundingClientRect().top,
        } : null);
        this.layoutId = '';
        if (this.indexOpenIds.includes(id)) {
          this.indexOpenIds = this.indexOpenIds.filter((openId) => openId !== id);
          this.openId = this.indexOpenIds[this.indexOpenIds.length - 1] || '';
        } else {
          this.indexOpenIds = [...this.indexOpenIds, id];
          this.openId = id;
        }
        if (viewportAnchor) {
          this.$nextTick(() => this.holdIndexViewportAnchor(viewportAnchor));
        }
        return;
      }
      if (this.openId === id) {
        this.close(id);
        return;
      }
      this.transitionGrid(id);
    },
    close(id = '') {
      if (this.mode === 'index') {
        this.indexOpenIds = id
          ? this.indexOpenIds.filter((openId) => openId !== id)
          : [];
        this.openId = this.indexOpenIds[this.indexOpenIds.length - 1] || '';
        this.layoutId = '';
        return;
      }
      this.transitionGrid('');
    },
    async transitionGrid(nextLayoutId) {
      if (this._gridTransition) {
        const isExistingEndpoint = nextLayoutId === this._gridTransitionFromId
          || nextLayoutId === this._gridTransitionToId;
        if (isExistingEndpoint && nextLayoutId !== this.layoutId) {
          const reversed = await this.reverseGridTransition(nextLayoutId);
          if (reversed) return;
        }
        if (this._gridTransition.skipTransition) this._gridTransition.skipTransition();
      }

      const previousLayoutId = this.layoutId;
      const activeId = nextLayoutId || this.layoutId;
      const viewportAnchor = this.consumeTargetViewportAnchor(activeId)
        || this.captureGridViewportAnchor(activeId);
      const transitionToken = (this._gridTransitionToken || 0) + 1;
      this._gridTransitionToken = transitionToken;
      const reduceMotion = window.matchMedia
        && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const cursorStartedAt = window.performance ? window.performance.now() : Date.now();
      const releaseCursorLock = !reduceMotion
        ? acquireInteractiveCursorLock()
        : null;
      if (releaseCursorLock) {
        if (!this._gridCursorReleases) this._gridCursorReleases = new Set();
        this._gridCursorReleases.add(releaseCursorLock);
      }
      this.transitionId = activeId;
      this.transitionAction = nextLayoutId ? 'expand' : 'collapse';
      await this.$nextTick();

      const applyLayout = async () => {
        this.layoutId = nextLayoutId;
        this.openId = nextLayoutId;
        await this.$nextTick();
        this.restoreGridViewportAnchor(viewportAnchor);
      };
      const finishTransition = () => {
        const now = window.performance ? window.performance.now() : Date.now();
        const remaining = reduceMotion
          ? 0
          : Math.max(0, GRID_CURSOR_SETTLE_MS - (now - cursorStartedAt));
        const timer = window.setTimeout(() => {
          if (this._gridCursorTimers) this._gridCursorTimers.delete(timer);
          if (releaseCursorLock) {
            releaseCursorLock();
            if (this._gridCursorReleases) this._gridCursorReleases.delete(releaseCursorLock);
          }
          if (this._gridTransitionToken !== transitionToken) return;
          window.clearTimeout(this._gridReverseTimer);
          this._gridTransition = null;
          this._gridTransitionFromId = '';
          this._gridTransitionToId = '';
          this.transitionId = '';
          this.transitionAction = '';
        }, remaining);
        if (!this._gridCursorTimers) this._gridCursorTimers = new Set();
        this._gridCursorTimers.add(timer);
      };
      if (!document.startViewTransition || reduceMotion) {
        await applyLayout();
        finishTransition();
        return;
      }

      let transition;
      try {
        transition = document.startViewTransition(applyLayout);
      } catch (error) {
        await applyLayout();
        finishTransition();
        return;
      }
      this._gridTransition = transition;
      this._gridTransitionFromId = previousLayoutId;
      this._gridTransitionToId = nextLayoutId;
      transition.finished.catch(() => {}).finally(finishTransition);
    },
    async reverseGridTransition(nextLayoutId) {
      const transition = this._gridTransition;
      if (!transition) return false;

      try {
        await transition.ready;
      } catch (error) {
        return false;
      }

      const animations = document.getAnimations().filter((animation) => {
        const pseudo = animation.effect && animation.effect.pseudoElement;
        return pseudo
          && pseudo.includes('collection-')
          && (animation.playState === 'running' || animation.playState === 'pending');
      });
      if (!animations.length) return false;

      this.layoutId = nextLayoutId;
      this.openId = nextLayoutId;
      this.transitionAction = nextLayoutId ? 'expand' : 'collapse';
      await this.$nextTick();
      animations.forEach((animation) => animation.reverse());

      const finishReverse = () => {
        if (this._gridTransition !== transition) return;
        if (transition.skipTransition) transition.skipTransition();
      };
      window.clearTimeout(this._gridReverseTimer);
      Promise.all(animations.map((animation) => animation.finished.catch(() => {})))
        .then(finishReverse);
      this._gridReverseTimer = window.setTimeout(finishReverse, 360);
      return true;
    },
    captureGridViewportAnchor(entryId) {
      if (!entryId) return null;
      const entry = this.entries.find((item) => item.id === entryId);
      const card = entry && document.getElementById(entry.anchor || entry.id);
      const summary = card && card.querySelector('.collection-card-summary');
      if (!card || !summary) return null;

      const cardRect = card.getBoundingClientRect();
      const summaryRect = summary.getBoundingClientRect();
      const header = document.querySelector('.header');
      const headerRect = header ? header.getBoundingClientRect() : null;
      const headerStyle = header ? window.getComputedStyle(header) : null;
      const headerFloats = headerStyle
        && (headerStyle.position === 'fixed' || headerStyle.position === 'sticky');
      const visibleTop = headerFloats && headerRect && headerRect.bottom > 0
        ? headerRect.bottom
        : 0;
      const clippedAtTop = cardRect.top < visibleTop - 1
        && summaryRect.bottom > visibleTop + 1;
      if (!clippedAtTop) return null;

      const entryIndex = this.entries.findIndex((item) => item.id === entryId);
      return {
        kind: 'summary-bottom',
        id: entry.anchor || entry.id,
        edge: entryIndex % 2 === 0 ? 'left' : 'right',
        summaryBottom: summaryRect.bottom
      };
    },
    consumeTargetViewportAnchor(entryId) {
      const anchor = this._targetViewportAnchor;
      if (!anchor || anchor.entryId !== entryId) return null;
      this._targetViewportAnchor = null;
      return anchor;
    },
    restoreGridViewportAnchor(anchor) {
      if (!anchor) return;
      const card = document.getElementById(anchor.id);
      if (!card) return;
      if (anchor.kind === 'top') {
        const deltaY = card.getBoundingClientRect().top - anchor.top;
        if (Math.abs(deltaY) > 0.5) window.scrollBy(0, deltaY);
        return;
      }
      const summary = card.querySelector('.collection-card-summary');
      if (!summary) return;
      // The selected card grows to the full row. Its left edge therefore stays
      // fixed for a left-column card and its right edge stays fixed for a
      // right-column card. Correct only the vertical scroll position so the
      // matching bottom corner remains at the same viewport height.
      const deltaY = summary.getBoundingClientRect().bottom - anchor.summaryBottom;
      if (Math.abs(deltaY) > 0.5) window.scrollBy(0, deltaY);
    },
    holdIndexViewportAnchor(anchor) {
      if (!anchor) return;
      if (this._indexAnchorFrame) cancelAnimationFrame(this._indexAnchorFrame);
      const startedAt = performance.now();
      const hold = () => {
        this.restoreGridViewportAnchor(anchor);
        if (performance.now() - startedAt < 430) {
          this._indexAnchorFrame = requestAnimationFrame(hold);
        } else {
          this._indexAnchorFrame = null;
        }
      };
      hold();
    }
  }
};
</script>

